sketch.css:
.psg{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:8px;padding:10px 12px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden;position:relative}
.psg *{box-sizing:border-box}
.summary{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px;font-size:12px;color:var(--muted);padding-bottom:8px;border-bottom:1px solid var(--border)}
.count{display:flex;align-items:center;gap:5px}
.count b{color:var(--text);font-weight:600;font-variant-numeric:tabular-nums}
.total{margin-left:auto;display:flex;align-items:baseline;gap:6px}
.total b{color:var(--text);font-weight:700;font-size:14px;font-variant-numeric:tabular-nums}
.total .pct{color:var(--accent);font-weight:600}
.groups{flex:1;min-height:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px;padding-right:2px}
.group{display:flex;flex-direction:column;gap:4px}
.header{display:flex;align-items:baseline;gap:6px;font-size:11.5px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.04em}
.header .sub{font-weight:400;text-transform:none;letter-spacing:0}
.tiles{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:4px}
.tile{display:flex;flex-direction:column;gap:3px;padding:5px 7px;border:1px solid var(--border);border-radius:6px;cursor:pointer;background:var(--window);min-width:0}
.tile:hover{background:var(--hover)}
.tile.selected{border-color:var(--accent);background:color-mix(in srgb,var(--accent) 10%,var(--window));box-shadow:inset 0 0 0 1px var(--accent)}
.line1{display:flex;align-items:center;gap:5px;min-width:0}
.dot{width:8px;height:8px;border-radius:50%;flex:none}
.dot.running{background:var(--positive)}
.dot.reduced{background:var(--warning)}
.dot.down{background:var(--negative)}
.dot.turnaround{background:var(--accent)}
.name{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px;font-weight:600}
.badge{flex:none;font-size:9.5px;font-weight:700;line-height:1;padding:2px 4px;border-radius:4px;color:var(--muted);background:var(--background);border:1px solid var(--border)}
.line2{display:flex;align-items:center;gap:6px}
.track{flex:1;height:4px;border-radius:2px;background:var(--background);overflow:hidden}
.bar{height:100%;border-radius:2px}
.bar.running{background:var(--positive)}
.bar.reduced{background:var(--warning)}
.bar.down,.bar.turnaround{background:transparent}
.rate{flex:none;width:34px;text-align:right;font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}
.tile.down .rate{color:var(--negative)}
.tile.turnaround .rate{color:var(--accent)}
.tip{position:absolute;display:none;pointer-events:none;z-index:2;padding:6px 9px;border-radius:6px;background:var(--text);color:var(--window);font-size:11.5px;line-height:1.45;box-shadow:0 4px 12px rgba(20,20,50,.18);white-space:nowrap}
.tip b{font-weight:600}
.empty{color:var(--muted);font-size:12px;padding:20px 0;text-align:center}

sketch.js:
function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const STATUS = { running: 'Running', reduced: 'Reduced', down: 'Down', turnaround: 'Turnaround' };
  const fmt = (v, d) => (+v || 0).toLocaleString('en-US', { minimumFractionDigits: d || 0, maximumFractionDigits: d || 0 });
  const host = root.querySelector('.psg');
  const plants = (props.plants || []).filter(p => p && p.id);
  const status = p => STATUS[p.status] ? p.status : 'running';

  // summary: counts by status, then the fleet's run rate against nameplate
  const counts = { running: 0, reduced: 0, down: 0, turnaround: 0 };
  let cap = 0, run = 0;
  plants.forEach(p => { counts[status(p)]++; cap += +p.capacityMmgy || 0; run += (+p.capacityMmgy || 0) * (+p.runRatePct || 0) / 100; });
  const sum = root.querySelector('.summary');
  sum.innerHTML = ['running', 'reduced', 'down', 'turnaround'].filter(s => s !== 'turnaround' || counts[s])
    .map(s => '<span class="count"><span class="dot ' + s + '"></span><b>' + counts[s] + '</b> ' + STATUS[s].toLowerCase() + '</span>').join('') +
    '<span class="total"><b>' + fmt(run) + '</b> / ' + fmt(cap) + ' MMgy <span class="pct">' + (cap ? Math.round(run / cap * 100) : 0) + '%</span></span>';

  // groups
  const by = props.groupBy || 'region';
  const groups = [];
  const index = {};
  plants.forEach(p => {
    const key = by === 'none' ? '' : by === 'ownership' ? (p.owned ? 'Owned' : '3rd-party') : (p.region || 'Other');
    if (!(key in index)) { index[key] = groups.length; groups.push({ key, plants: [] }); }
    groups[index[key]].plants.push(p);
  });
  if (by === 'ownership') groups.sort((a, b) => a.key === 'Owned' ? -1 : b.key === 'Owned' ? 1 : 0);

  const box = root.querySelector('.groups');
  if (!plants.length) { box.innerHTML = '<div class="empty">No plants</div>'; return; }
  box.innerHTML = groups.map(g => {
    let gcap = 0, grun = 0;
    g.plants.forEach(p => { gcap += +p.capacityMmgy || 0; grun += (+p.capacityMmgy || 0) * (+p.runRatePct || 0) / 100; });
    const head = g.key ? '<div class="header">' + esc(g.key) + '<span class="sub">' + g.plants.length + ' plants · ' + (gcap ? Math.round(grun / gcap * 100) : 0) + '%</span></div>' : '';
    return '<div class="group">' + head + '<div class="tiles">' + g.plants.map(p => {
      const s = status(p), r = Math.max(0, +p.runRatePct || 0);
      return '<div class="tile ' + s + (p.id === props.selected ? ' selected' : '') + '" data-id="' + esc(p.id) + '">' +
        '<div class="line1"><span class="dot ' + s + '"></span><span class="name">' + esc(p.name) + '</span>' + (p.owned ? '' : '<span class="badge">3P</span>') + '</div>' +
        '<div class="line2"><span class="track"><span class="bar ' + s + '" style="width:' + Math.min(100, r) + '%;display:block"></span></span><span class="rate">' + (s === 'down' || s === 'turnaround' ? (s === 'down' ? 'Down' : 'TA') : r.toFixed(0) + '%') + '</span></div></div>';
    }).join('') + '</div></div>';
  }).join('');

  // tiles: click selects, hover shows the tooltip
  const tip = root.querySelector('.tip');
  const byId = {};
  plants.forEach(p => byId[p.id] = p);
  box.querySelectorAll('.tile').forEach(el => {
    const p = byId[el.dataset.id];
    el.onclick = () => fire('plantSelected', { plantId: p.id, selected: p.id });
    el.onmouseenter = () => {
      tip.innerHTML = '<b>' + esc(p.name) + '</b> · ' + esc(p.region) + (p.owned ? '' : ' · 3rd-party') + '<br>' +
        'Status: <b>' + STATUS[status(p)] + '</b><br>Capacity: <b>' + fmt(p.capacityMmgy) + ' MMgy</b><br>' +
        'Run rate: <b>' + fmt(p.runRatePct) + '%</b> · Today: <b>' + fmt(p.productionKgal) + ' kgal</b>';
      tip.style.display = 'block';
      const hr = host.getBoundingClientRect(), er = el.getBoundingClientRect();
      let left = er.left - hr.left, top = er.bottom - hr.top + 4;
      if (left + tip.offsetWidth > hr.width - 4) left = hr.width - tip.offsetWidth - 4;
      if (top + tip.offsetHeight > hr.height - 4) top = er.top - hr.top - tip.offsetHeight - 4;
      tip.style.left = Math.max(4, left) + 'px'; tip.style.top = top + 'px';
    };
    el.onmouseleave = () => tip.style.display = 'none';
  });
}
